                                                sp1.atomic_radius +
                                                self.cutoff)

    for site2, dist in neighbors:
        sp2 = site2.specie

        if sp1 in bp_dict and sp2 in bp_dict:
            expected_dist = bp_dict[sp1] + bp_dict[sp2]
        else:
            expected_dist = sp1.atomic_radius + sp2.atomic_radius

